        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                rings.append((r, c))

    # Project each ring along the axis perpendicular to its supporting rail.
    rays = []
    for r, c in rings:
        on_h = r in horizontal
        on_v = c in vertical
        if on_v and not on_h:
            rays.append(("h", r, c))
        elif on_h and not on_v:
            rays.append(("v", r, c))
        elif vertical and not horizontal:
            rays.append(("h", r, c))
        elif horizontal and not vertical:
            rays.append(("v", r, c))
        elif on_v:
            rays.append(("h", r, c))
        elif on_h:
            rays.append(("v", r, c))

    # Draw full rays, preserving the original shapes and rail cells.
    for direction, r, c in rays:
        if direction == "h":
            for x in range(w):
                if out[r][x] == 0:
                    out[r][x] = 1
        else:
            for y in range(h):
                if out[y][c] == 0:
                    out[y][c] = 1

